const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;

    const N = parseInt(input[0], 10);
    const P = input[1];

    // Contagem total de cada caractere
    const totalCount = new Int32Array(26);
    for (let i = 0; i < N; i++) {
        totalCount[P.charCodeAt(i) - 97]++;
    }

    // Encontrar divisores próprios de N em ordem crescente
    const divisors = [];
    for (let d = 1; d * d <= N; d++) {
        if (N % d === 0) {
            divisors.push(d);
            if (d * d !== N && d !== 1) {
                divisors.push(N / d);
            }
        }
    }
    divisors.sort((a, b) => a - b);

    const rootCount = new Int32Array(26);
    const blockCount = new Int32Array(26);

    for (let i = 0; i < divisors.length; i++) {
        const L = divisors[i];
        if (L === N) continue; // poligrama deve ter pelo menos 2 partes

        const k = N / L;

        // Contar frequência do primeiro bloco (raiz candidata)
        rootCount.fill(0);
        for (let j = 0; j < L; j++) {
            rootCount[P.charCodeAt(j) - 97]++;
        }

        // Verificação rápida: totalCount[c] deve ser exatamente k * rootCount[c]
        let possible = true;
        for (let c = 0; c < 26; c++) {
            if (totalCount[c] !== rootCount[c] * k) {
                possible = false;
                break;
            }
        }

        if (!possible) continue;

        // Se passou no teste rápido, verificar todos os outros blocos
        let allMatch = true;
        for (let b = 1; b < k; b++) {
            blockCount.fill(0);
            const start = b * L;
            const end = start + L;
            for (let j = start; j < end; j++) {
                blockCount[P.charCodeAt(j) - 97]++;
            }

            for (let c = 0; c < 26; c++) {
                if (blockCount[c] !== rootCount[c]) {
                    allMatch = false;
                    break;
                }
            }

            if (!allMatch) break;
        }

        if (allMatch) {
            console.log(P.substring(0, L));
            return;
        }
    }

    console.log('*');
}

solve();
